  "2019 P2 Q10(a)": {"skill":"Find the area of a running track around a sports ground.","method":"5 marks","moves":["The curved ends make two circles, one inside the other. What are their radii?","Find the area of the larger circle.","Find the area of the smaller circle.","Take one from the other for the curved parts of the track.","Find the area of the two straight parts of the track.","Add the curved and straight parts."],"marks":[0,1,1,1,1,1],"shows":[null,"\\(\\pi \\times 45.35^2 = 6461.07\\ldots\\)","\\(\\pi \\times 36.8^2 = 4254.47\\ldots\\)","\\(2206.599\\ldots\\)","\\(8.55 \\times 84.4 \\times 2 = 1443.24\\)",null],"watch":{"at":1,"text":"Use \\(\\pi r^2\\) for each circle's area, with its radius."}},
