  "2025 P2 Q7(a)": {"skill":"Find the date and local time the ship left, across a time zone.","method":"3 marks","moves":["How many days and hours are 180 hours?","Change the sailing time to days and hours.","Change the arrival time to Southampton time.","Count back the sailing time to find the date and time it left."],"marks":[0,1,1,1],"shows":[null,"\\((180 \\div 24 =)\\ 7.5\\) or 7 days 12 hours","\\((04{:}00 + 5\\text{ hours} =)\\ 09{:}00\\), or \\((16{:}00 + 5\\text{ hours} =)\\ 21{:}00\\), or (7 days 12 hours \\(-\\) 5 hours \\(=\\)) 7 days and 7 hours",null],"watch":{"at":2,"text":"New York is behind Southampton, so Southampton's clock reads 5 hours later."}},
  "2025 P2 Q7(b)": {"skill":"Find an exchange rate from US dollars to Canadian dollars.","method":"3 marks","moves":["How many US dollars did James have left after 7 days?","Change £1500 to US dollars.","Take off what he spent in the 7 days.","Divide the Canadian dollars he received by the US dollars he had left."],"marks":[0,1,1,1],"shows":[null,"\\((1500 \\times 1.28 =)\\ 1920\\)","\\((1920 - 130 \\times 7 =)\\ 1010\\)",null],"watch":{"at":3,"text":"Give the rate to at least 2 decimal places."}},
